import{z as d,x as B,o as i,c as m,q as l,j as s,D as t,d as r,s as o,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"最优二叉搜索树","description":"","frontmatter":{"title":"最优二叉搜索树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/optimal-bst.md","filePath":"cs/optimal-bst.md","lastUpdated":1791063341000}'),h={name:"cs/optimal-bst.md"};function E(u,a,_,A,D,T){const n=B("Mermaid");return i(),m("div",null,[a[2]||(a[2]=l('<h1 id="最优二叉搜索树" tabindex="-1">最优二叉搜索树 <a class="header-anchor" href="#最优二叉搜索树" aria-label="Permalink to &quot;最优二叉搜索树&quot;">​</a></h1><div class="epigraph"><p>关键字概率已知时，BST 的期望比较次数由区间 DP 最小化；四边形不等式把 $O(n^3)$ 收到 $O(n^2)$。</p><footer>—— 据 Knuth, Optimum Binary Search Trees, 1971；CLRS 第 15.5 节整理</footer></div><p>上一课<a href="/cs/sequence-alignment">序列比对</a>在两序列的格图上走。本课换输入：一个有序关键字列 \\(k_1\\lt \\cdots\\lt k_n\\)，关键字访问概率 \\(p_i\\)、空隙命中概率 \\(q_i\\)。缺口是最优 BST：若根选 \\(k_r\\)，左右子树各自最优。主干<a href="/cs/interval-dp">区间 DP</a>已给过矩阵链的形状；本课把概率加权写清，Knuth 优化留一半给下一课矩阵链对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记 \\(e[i,j]\\) 为关键字 \\(i..j\\) 构成子树的最优期望比较次数，\\(w[i,j]\\) 为这一段的概率和（含空隙）。转移：\\(e[i,j]=\\min_r\\left(e[i,r-1]+e[r+1,j]\\right)+w[i,j]\\)——选 \\(k_r\\) 当根，左右子树整体加深一层，增量正是整段概率和 \\(w\\)。朴素枚举 \\(r\\)，\\(O(n^3)\\)。Knuth 的观察：最优根满足 \\(opt[i,j-1]\\le opt[i,j]\\le opt[i+1,j]\\)，\\(r\\) 的枚举范围随区间收缩，总代价降到 \\(O(n^2)\\)。</p><p>缺口是按已知概率最小化期望代价；AVL 那类平衡树不读 \\(p_i\\)，只保证形状平衡，两者目标不同。</p><h3 id="不是哈夫曼" tabindex="-1">不是哈夫曼 <a class="header-anchor" href="#不是哈夫曼" aria-label="Permalink to &quot;不是哈夫曼&quot;">​</a></h3><p>最容易混的是哈夫曼：那是最优前缀码，码字不要求支持有序检索。BST 必须中序关键字有序——编码最优与检索有序是两个不同约束，哈夫曼树一般不满足 BST 的中序条件，不要拿它当最优 BST。</p><p><span class="marginnote">Knuth 1971。CLRS 15.5。下一课矩阵链同一 Knuth 单调。Mehlhorn 近似最优 BST 点名。</span></p><p><span class="marginnote">数字实例：两个关键字 \\(p_1=0.9\\)、\\(p_2=0.1\\)——把热的 \\(k_1\\) 放根、冷的放孩子，期望比较 \\(1\\times0.9+2\\times0.1=1.1\\) 次；反过来摆则是 \\(1\\times0.1+2\\times0.9=1.9\\) 次，几乎翻倍。「高频键放浅处」的收益压倒「形状要平衡」的直觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现要点：概率做前缀和，\\(w\\) 可 \\(O(1)\\) 回答；按区间长度从小到大填 \\(e\\) 与 \\(opt\\)；根决策存进 \\(root[i,j]\\)，重建树时按它递归展开。模型边界：这是静态概率下的静态树；访问分布会变时，是自适应 splay 的另一套模型。</p>',12)),(i(),s(p,null,{default:t(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A6%82%E7%8E%87%20p%2C%20q%22%5D%20--%3E%20E%5B%22e%5Bi%2Cj%5D%20%E5%8C%BA%E9%97%B4%20DP%22%5D%0A%20%20E%20--%3E%20KNU%5B%22opt%20%E5%8D%95%E8%B0%83%20O(n%5E2)%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：前缀和就是把 \\(p,q\\) 从左到右累加成一列「累计概率」；任意一段的 \\(w[i,j]\\) 用两次累加值一减就出，\\(O(1)\\)。不做这一步，每次转移都还要再 \\(O(n)\\) 求一遍和，白慢一档。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"每一项都有语义：期望代价 = 子树期望 + 经过根的代价，而任何一次访问都要经过子树根，所以整段加 \\(w[i,j]\\)。最优子结构成立：整体最优时左右子树仍各自最优。Knuth 单调（四边形不等式）来自 \\(w\\) 满足四边形不等式这一性质，不是从树形凭空来的。与矩阵链对照：切点一个是「子树根」、一个是「最后一次相乘」，含义不同，单调性同类。",-1)),a[6]||(a[6]=e("p",null,"转移式 \\(e[i,j]\\) 每一项为什么长这样：",-1)),(i(),s(p,null,{default:t(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEG%5B%22%E5%8C%BA%E9%97%B4%20i..j%22%5D%20--%3E%20ROOT%5B%22%E9%80%89%20k_r%20%E5%BD%93%E6%A0%B9%22%5D%0A%20%20ROOT%20--%3E%20L%5B%22%E5%B7%A6%E5%AD%90%E6%A0%91%20e%5Bi%2C%20r-1%5D%22%5D%0A%20%20ROOT%20--%3E%20R%5B%22%E5%8F%B3%E5%AD%90%E6%A0%91%20e%5Br%2B1%2C%20j%5D%22%5D%0A%20%20L%20--%3E%20PLUS%5B%22%E6%95%B4%E6%AE%B5%E5%8A%A0%E6%B7%B1%E4%B8%80%E5%B1%82%3A%20%E5%8A%A0%20w%5Bi%2Cj%5D%22%5D%0A%20%20R%20--%3E%20PLUS%0A%20%20PLUS%20--%3E%20E%5B%22e%5Bi%2Cj%5D%20%3D%20min_r%20%E4%B8%8A%E5%BC%8F%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">直觉类比：\\(w[i,j]\\) 是「这一段所有人的总概率」。树每深一层，子树里每一次查找都要多比一次——等于给整段人统一加一层过路费，所以增量是整段的概率和，而不是只给根算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写动态最优 BST 猜想——splay 的动态最优性仍是开放问题；不写熵界证明全文。后课默认：已知独立访问概率时，最优 BST 走区间 DP 加 Knuth 优化。下一课矩阵链与 Knuth 优化收束本单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优 BST 是概率加权的区间 DP。</li><li>Knuth 根单调把 \\(O(n^3)\\) 收到 \\(O(n^2)\\)。</li><li>它不是哈夫曼，也不是平衡 BST。</li><li>出处：Knuth, 1971；CLRS 第 15.5 节。</li></ul>',5))])}const f=d(h,[["render",E]]);export{c as __pageData,f as default};
